const staffErrorMarkup=error=>{const value=staffErrorMessage(error);return value&&typeof value==='object'?uiLeaf(value.key,value.params):esc(value);};
const entryLanguages=new WeakMap();
function paintCabinetLabels(host){
 paintStaffUi(host);
 for(const [id,labels]of [['staff-format',{surah:'staffUi.cabinetFullSurahs',verse:'staffUi.cabinetByVerse'}],['staff-group',{'':'staffUi.cabinetOtherReciters',makkah:'staffUi.cabinetMakkahImams',madinah:'staffUi.cabinetMadinahImams'}],['staff-existing',{'':'staffUi.cabinetChoose'}]]){
  const select=host.querySelector('#'+id);if(!select)continue;const selected=select.value;
  for(const option of select.options){const key=labels[option.value];if(key){const label=t(key);if(option.textContent!==label)option.textContent=label;}}
  if(select.value!==selected)select.value=selected;
 }
}
